     <section class="card" aria-labelledby="form-title">
       <h1 id="form-title">Notification Preferences</h1>
       <p class="intro">Choose how you would like us to contact you.</p>

       <form id="notification-form">
         <div class="form-field">
           <fieldset>
             <legend>How do you prefer to receive notifications?</legend>

             <label class="radio-option" for="notifications-email">
